package main

import (
 "encoding/json"
 "flag"
 "fmt"
 "io"
 "net/http"
 "os"
 "strconv"
 "strings"
 "time"
)

// A tiny actual business protocol fixture. Docker/Swarm/configuration behavior
// is always performed by the real daemon; this program never imitates its API.
func main() {
 mode:=flag.String("mode","backend","frontend or backend")
 listen:=flag.String("listen","127.0.0.1:19081","private namespace loopback only")
 peer:=flag.String("peer","http://127.0.0.1:19081","backend address")
 config:=flag.String("config","/run/protocol","actual Swarm Config file")
 flag.Parse()
 data,err:=os.ReadFile(*config);if err!=nil {panic(err)}
 text:=strings.TrimSpace(string(data));version:=0
 if strings.HasPrefix(text,"{") {var d struct{Protocol int `json:"protocol"`};if err=json.Unmarshal(data,&d);err!=nil{panic(err)};version=d.Protocol} else {version,err=strconv.Atoi(text);if err!=nil{panic(err)}}
 if version!=1 && version!=2 {panic("unsupported protocol")}
 fmt.Printf("loaded mode=%s protocol=%d config=%s\n",*mode,version,*config)
 client:=http.Client{Timeout:2*time.Second}
 http.HandleFunc("/probe",func(w http.ResponseWriter,r *http.Request){
  w.Header().Set("Content-Type","application/json")
  if *mode=="backend" {
   requested,_:=strconv.Atoi(r.Header.Get("X-Protocol"));compatible:=requested==1 || (version==2 && requested==2)
   if !compatible {w.WriteHeader(http.StatusConflict)}
   json.NewEncoder(w).Encode(map[string]any{"backend":version,"requested":requested,"compatible":compatible});return
  }
  req,err:=http.NewRequest(http.MethodGet,*peer+"/probe",nil);if err!=nil {http.Error(w,err.Error(),500);return}
  req.Header.Set("X-Protocol",strconv.Itoa(version));response,err:=client.Do(req)
  if err!=nil {http.Error(w,err.Error(),503);return};defer response.Body.Close()
  var result map[string]any;body,_:=io.ReadAll(response.Body)
  if err=json.Unmarshal(body,&result);err!=nil {http.Error(w,string(body),502);return}
  result["frontend"]=version;w.WriteHeader(response.StatusCode);json.NewEncoder(w).Encode(result)
 })
 if err=http.ListenAndServe(*listen,nil);err!=nil {panic(err)}
}

